/**
 * JSS Lesson Note Templates — Part 2
 * JSS 1: Basic Science & Computer Studies — All 3 Terms × 12 Weeks
 * JSS 2: English Language & Mathematics — All 3 Terms × 12 Weeks
 * Original content based on Nigerian NERDC curriculum.
 */

import type { LNTemplate } from "./seed-jss-lesson-notes-1";

function lnt(
  className: string, subjectName: string, level: string,
  term: string, weekNumber: number, topic: string,
  objectives: string, entryBehaviour: string, materials: string,
  content: string, teacherActs: string, studentActs: string,
  evalQ: string, assign: string, refs: string
): LNTemplate {
  return {
    title: `${className} ${subjectName} – ${topic}`, level, className, subjectName,
    term, weekNumber, topic, duration: "40 minutes",
    objectives, entryBehaviour, instructionalMaterials: materials,
    content, teacherActivities: teacherActs, studentActivities: studentActs,
    evaluationQuestions: evalQ, assignments: assign, references: refs,
  };
}

